import React from "react"

import Select from "../ui/Select"
import Checkbox from "../ui/Checkbox"
import { COMPANIES } from "../../data/companies"

/**
 * The fundamentals filter rail.
 *
 * These filters really do narrow the universe — the parent uses `matches()`
 * below to shrink the ticker list, and the rail shows the surviving count. A
 * filter panel that looked active but changed nothing would be worse than no
 * panel at all.
 *
 * Where a criterion has no field behind it in this dataset (SEC filings,
 * liquidity, OTC status) the rule is approximated from data that does exist and
 * the approximation is stated in the control's title attribute, rather than
 * being silently inert.
 */

export const DEFAULT_FILTERS = {
  marketCap: "any",
  revenueGrowth: "any",
  profitability: "any",
  exchange: "any",
  hasFilings: false,
  excludeOtc: false,
  minLiquidity: false,
  positiveRevenue: false,
  credibleOnly: false,
}

const MARKET_CAP_OPTIONS = [
  { label: "Any market cap", value: "any" },
  { label: "Mega cap (over $200B)", value: "mega" },
  { label: "Large cap ($10B–$200B)", value: "large" },
  { label: "Mid cap ($2B–$10B)", value: "mid" },
  { label: "Small cap (under $2B)", value: "small" },
]

const GROWTH_OPTIONS = [
  { label: "Any growth", value: "any" },
  { label: "Over 40%", value: "40" },
  { label: "Over 20%", value: "20" },
  { label: "Over 10%", value: "10" },
  { label: "Positive", value: "0" },
]

const PROFIT_OPTIONS = [
  { label: "Any profitability", value: "any" },
  { label: "Profitable", value: "profitable" },
  { label: "Loss-making", value: "loss" },
  { label: "Net margin over 20%", value: "margin20" },
]

const EXCHANGE_OPTIONS = [
  { label: "Any exchange", value: "any" },
  { label: "NASDAQ", value: "NASDAQ" },
  { label: "NYSE", value: "NYSE" },
]

/** Does one company survive the current filter set? */
export function matches(company, filters) {
  const cap = company.marketCap
  if (filters.marketCap === "mega" && !(cap >= 200e9)) return false
  if (filters.marketCap === "large" && !(cap >= 10e9 && cap < 200e9)) return false
  if (filters.marketCap === "mid" && !(cap >= 2e9 && cap < 10e9)) return false
  if (filters.marketCap === "small" && !(cap < 2e9)) return false

  if (filters.revenueGrowth !== "any") {
    const threshold = Number(filters.revenueGrowth) / 100
    const growth = company.revenueGrowthYoY
    if (growth === null || growth <= threshold) return false
  }

  if (filters.profitability === "profitable" && !(company.netIncomeTTM > 0)) return false
  if (filters.profitability === "loss" && !(company.netIncomeTTM < 0)) return false
  if (filters.profitability === "margin20" && !(company.netMargin !== null && company.netMargin > 0.2))
    return false

  if (filters.exchange !== "any" && company.exchange !== filters.exchange) return false

  // Approximations, each stated in the UI rather than pretending to be exact.
  if (filters.hasFilings && !(company.financials && company.financials.length >= 5)) return false
  if (filters.excludeOtc && !["NASDAQ", "NYSE"].includes(company.exchange)) return false
  if (filters.minLiquidity && !(company.avgVolume >= 5e6)) return false
  if (filters.positiveRevenue && !(company.revenueTTM > 0)) return false
  if (filters.credibleOnly && !(company.marketCap >= 1e9 && company.revenueTTM > 0)) return false

  return true
}

export function filterCompanies(filters) {
  return COMPANIES.filter(c => matches(c, filters))
}

const CHECKS = [
  {
    key: "hasFilings",
    label: "Has recent SEC filings",
    hint: "Approximated as five consecutive years of reported financials.",
  },
  {
    key: "excludeOtc",
    label: "Exclude OTC",
    hint: "Keeps NASDAQ and NYSE listings only.",
  },
  {
    key: "minLiquidity",
    label: "Minimum liquidity",
    hint: "Average daily volume of at least 5M shares.",
  },
  {
    key: "positiveRevenue",
    label: "Positive revenue",
    hint: "Excludes pre-revenue companies.",
  },
  {
    key: "credibleOnly",
    label: "Show only credible companies",
    hint: "At least $1B market cap and some reported revenue.",
  },
]

export default function FilterRail({ filters, onChange, onApply, onReset, matchCount, total }) {
  const set = (key, value) => onChange({ ...filters, [key]: value })

  return (
    <aside className="filter-rail">
      <div className="filter-rail__head">
        <h2 className="filter-rail__title">Fundamental filters</h2>
        <p className="filter-rail__note">Find companies that match your criteria.</p>
      </div>

      <div className="filter-rail__body">
        <div className="filter-rail__group">
          <Select
            label="Market cap"
            options={MARKET_CAP_OPTIONS}
            value={filters.marketCap}
            onChange={v => set("marketCap", v)}
          />
          <Select
            label="Revenue growth (YoY)"
            options={GROWTH_OPTIONS}
            value={filters.revenueGrowth}
            onChange={v => set("revenueGrowth", v)}
          />
          <Select
            label="Profitability"
            options={PROFIT_OPTIONS}
            value={filters.profitability}
            onChange={v => set("profitability", v)}
          />
          <Select
            label="Exchange"
            options={EXCHANGE_OPTIONS}
            value={filters.exchange}
            onChange={v => set("exchange", v)}
          />
        </div>

        <div className="filter-rail__checks">
          {CHECKS.map(check => (
            <span className="filter-rail__check" key={check.key} title={check.hint}>
              <Checkbox
                label={check.label}
                checked={filters[check.key]}
                onChange={e => set(check.key, e.target.checked)}
              />
            </span>
          ))}
        </div>

        <p className="filter-rail__count">
          <strong>{matchCount}</strong> of {total} companies match
        </p>

        <div className="filter-rail__actions">
          <button type="button" className="btn btn--primary" onClick={onApply}>
            Apply filters
          </button>
          <button type="button" className="btn btn--ghost" onClick={onReset}>
            Reset
          </button>
        </div>
      </div>
    </aside>
  )
}
